#include "ir_free_helpers.h"
#include "optimizer_control_flow.h"

/**
 * @brief Test whether any successor needs the current slot value.
 *
 * @param term The terminator to test.
 * @param needed What blocks read the current slot value before writing to it.
 * @return true if any successor needs the current slot value, false otherwise.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Eliminate stores killed on every path using backward slot liveness.
static bool is_value_needed(const IrBlockTerminator* term, const bool* needed) {
  switch (term->type) {
    case IR_TERMINATOR_JUMP:
      return needed[term->value.jump_target];

    case IR_TERMINATOR_CONDITIONAL:
      return needed[term->value.conditional_target.true_target] ||
             needed[term->value.conditional_target.false_target];

    default:
      return false;
  }
}

bool optimizer_remove_unused_stores(Ctx* ctx, IrFunctionId fid) {
  IrFunction* function = &ctx->ir.functions.data[fid];

  // Reuse allocated memory from optimizer context
  // What is the first thing we do with a stack slot in each block
  size_t* first_access = ctx->optimizer.block_data;
  enum { NO_ACCESS, READ_VALUE, OVERWRITE_VALUE };

  // Whether each block needs the value of the stack slot at the beginning
  bool* live = ctx->optimizer.blocks;

  bool changed = false;

  // Go through each stack slot
  for (IrStackSlotId sid = 0; sid < function->slots.count; sid++) {
    // Prepare live and first_access for this stack slot
    for (IrBlockId bid = 0; bid < function->blocks.count; bid++) {
      IrInstructionArray* instructions =
          &function->blocks.data[bid].instructions;

      // Initialize live and first_access for this block
      first_access[bid] = NO_ACCESS;
      live[bid] = false;

      // Look for the first instruction that uses this slot
      for (size_t i = 0; i < instructions->count; i++) {
        const IrInstruction* inst = &instructions->data[i];

        if (inst->type == IR_INST_LOAD && inst->operands.load.source == sid) {
          first_access[bid] = READ_VALUE;
          break;
        }

        if (inst->type == IR_INST_STORE && inst->operands.store.target == sid) {
          first_access[bid] = OVERWRITE_VALUE;
          break;
        }
      }
    }

    // A block with no local access can still pass the value to a successor.
    // Iterate because backedges can make that requirement reach an earlier
    // block.
    bool progress;
    do {
      progress = false;

      for (IrBlockId bid = function->blocks.count; bid-- > 0;) {
        if (live[bid])
          continue;

        const IrBlockTerminator* term = &function->blocks.data[bid].terminator;
        if (first_access[bid] == READ_VALUE ||
            (first_access[bid] == NO_ACCESS && is_value_needed(term, live))) {
          live[bid] = true;
          progress = true;
        }
      }
    } while (progress);

    // Remove unused stores
    for (IrBlockId bid = 0; bid < function->blocks.count; bid++) {
      IrBlock* block = &function->blocks.data[bid];

      bool needed = is_value_needed(&block->terminator, live);

      for (size_t inst_id = block->instructions.count; inst_id-- > 0;) {
        IrInstruction* instruction = &block->instructions.data[inst_id];

        if (instruction->type == IR_INST_LOAD &&
            instruction->operands.load.source == sid) {
          needed = true;
        } else if (instruction->type == IR_INST_STORE &&
                   instruction->operands.store.target == sid) {
          if (!needed) {
            ir_free_instruction(instruction);
            array_remove(ctx, &block->instructions, inst_id);
            changed = true;
          }

          needed = false;
        }
      }
    }
  }

  return changed;
}
